        .focused(is_focused)
        .hovered(is_hovered)
        .on_hover(cx.listener(move |this, is_hovered: &bool, _window, cx| {
            if *is_hovered {
                this.hovered_thread_index = Some(ix);
            } else if this.hovered_thread_index == Some(ix) {
                this.hovered_thread_index = None;
            }
